window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 20000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await fn()) return true; await sleep(150) } return false };
window.nav = async (name) => { const b = [...document.querySelectorAll('nav button')].find((x) => x.textContent.trim() === name); if (!b) return 'NO NAV ' + name; b.click(); await sleep(2500); return 'nav ' + name };
window.check = (label, ok, got) => (ok ? 'OK ' : 'MISMATCH ') + label + ' got ' + JSON.stringify(got);
window.trigger = () => document.querySelector('button[aria-label^="League: "]');
window.league = () => trigger()?.getAttribute('aria-label')?.replace('League: ', '') ?? null;
window.statusLine = () => document.querySelector('[title="See what is loaded"]')?.textContent.trim() ?? null;
window.h1 = () => document.querySelector('main h1')?.textContent.trim() ?? null;
window.mainText = () => document.querySelector('main')?.innerText ?? '';
window.settled = () => until(() => !/Loading|loading…/.test(mainText()) && mainText().length > 0, 20000);
window.switchTo = async (name) => { const t = trigger(); if (!t) return 'NO MENU'; t.focus(); t.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await until(() => document.querySelectorAll('[role=menuitemradio]').length > 0, 3000); const item = [...document.querySelectorAll('[role=menuitemradio]')].find((x) => x.textContent.startsWith(name)); if (!item) return 'NO ITEM ' + name; item.click(); await until(() => league() === name, 5000); await sleep(3000); await settled(); await sleep(1500); return league() };
window.bad = (t) => /stats yet|could not be opened|unknown league|Something went wrong|Error:|has no .* recipe|No standings are published/.test(t);
window.fingerprint = () => ({ h1: h1(), text: mainText().slice(0, 600) });
window.collegeReads = (name, expect) => { const t = mainText(); const missing = expect.filter((x) => !t.includes(x)); return { ok: league() === name && !bad(t) && /\d/.test(t) && missing.length === 0, missing, h1: h1(), text: t.slice(0, 300), status: statusLine() } };
window.trip = async (screen, expect) => { await nav(screen); if (league() !== 'NBA') await switchTo('NBA'); await settled(); await sleep(2000); const nba = fingerprint(); const out = { screen }; for (const name of ['NCAA Men', 'NCAA Women']) { await switchTo(name); out[name] = collegeReads(name, expect[name] ?? []) } const w = await switchTo('WNBA'); out.wnba = { league: w, h1: h1(), ok: w === 'WNBA' && !bad(mainText()) }; const n = await switchTo('NBA'); await sleep(2000); const back = fingerprint(); const same = JSON.stringify(back) === JSON.stringify(nba); return check(screen + ': both NCAA leagues read their game and season tables with no error; the WNBA reads its data; the NBA comes back unchanged', out['NCAA Men'].ok && out['NCAA Women'].ok && out.wnba.ok && n === 'NBA' && same, same ? out : { ...out, nba, back }) };
